package com.example.partner;

import java.time.Instant;
import java.util.concurrent.ConcurrentHashMap;

import org.springframework.stereotype.Component;
import org.springframework.web.client.RestClient;

@Component
public class PartnerTokenClient {
    private final RestClient http;
    private final ConcurrentHashMap<String, Token> tokens = new ConcurrentHashMap<>();

    public PartnerTokenClient(RestClient partnerRestClient) {
        this.http = partnerRestClient;
    }

    public String token(String tenantId) {
        return tokens.compute(tenantId, (id, current) ->
            current != null && current.isValid(Instant.now()) ? current : fetch(id)).value();
    }

    private Token fetch(String tenantId) {
        TokenResponse response = http.post()
            .uri("/tenants/{id}/oauth/token", tenantId)
            .retrieve()
            .body(TokenResponse.class);
        return new Token(response.accessToken(), Instant.now().plusSeconds(response.expiresIn()));
    }

    private record Token(String value, Instant expiresAt) {
        boolean isValid(Instant now) {
            return now.isBefore(expiresAt);
        }
    }
}

import java.util.concurrent.locks.ReentrantLock;

    private final ConcurrentHashMap<String, Token> tokens = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, ReentrantLock> locks = new ConcurrentHashMap<>();

    public String token(String tenantId) {
        Token cached = tokens.get(tenantId);
        if (cached != null && cached.isValid(Instant.now())) {
            return cached.value();
        }
        ReentrantLock lock = locks.computeIfAbsent(tenantId, id -> new ReentrantLock());
        lock.lock();
        try {
            Token current = tokens.get(tenantId);
            if (current != null && current.isValid(Instant.now())) {
                return current.value();
            }
            Token fresh = fetch(tenantId);
            tokens.put(tenantId, fresh);
            return fresh.value();
        } finally {
            lock.unlock();
        }
    }
